/// Build a minimal [`Brand`] for use in export tests.
fn minimal_brand() -> Brand {
    use slideforge_types::span::SourceSpan;
    Brand {
        name: Arc::from("test-brand"),
        palette: BrandPalette {
            primary: Arc::from("#003087"),
            secondary: Arc::from("#0066CC"),
            accent: Arc::from("#FF6B35"),
            neutral: Arc::from("#F5F5F5"),
        },
        fonts: BrandFonts {
            heading: Arc::from("Calibri Light"),
            body: Arc::from("Calibri"),
            mono: Arc::from("Courier New"),
        },
        layouts: vec![],
        span: SourceSpan::default(),
    }
}

/// Build a minimal [`Deck`] with `lang "en-US"`.
fn minimal_deck() -> Deck {
    Deck {
        slides: vec![],
        vars: OrderedMap::new(),
        metadata: DeckMetadata {
            title: Some(Arc::from("Test Deck")),
            slideforge_version: Arc::from("0.1.0"),
            lang: Some(Arc::from("en-US")),
            author: None,
            section_order: None,
        },
        registers: OrderedMap::new(),
        section_blocks: vec![],
    }
}

/// Build a [`LaidOutSlide`] with a given title and no register content.
fn make_slide(title: &str) -> LaidOutSlide {
    LaidOutSlide {
        source_index: 0,
        slide_type_keyword: Arc::from("content"),
        frames: vec![Frame {
            bbox: BoundingBox {
                x: Emu(0),
                y: Emu(0),
                width: Emu(9_144_000),
                height: Emu(5_143_500),
            },
            content: FrameContent::Title(Arc::from(title)),
            text_flow: None,
        }],
        speaker_notes: None,
        register_tags: vec![],
        register_content: vec![RegisteredContent::plain(
            Register::Report,
            Arc::from(format!("Report paragraph for '{title}'")),
        )],
    }
}

/// Build an auto-generated `executive_summary` [`GeneratedSection`] from a
/// list of takeaway strings.
fn make_executive_summary_section(takeaways: &[&str]) -> GeneratedSection {
    GeneratedSection {
        kind: SectionKind::ExecutiveSummary,
        source: SectionSource::AutoGenerated,
        items: takeaways
            .iter()
            .map(|t| SectionItem::TakeawayBullet(Arc::from(*t)))
            .collect(),
        heading: Arc::from("Executive Summary"),
        target_formats: vec![OutputFormat::Docx, OutputFormat::Pdf],
        register_content: vec![],
    }
}

/// Build an auto-generated `risk_register` [`GeneratedSection`] from a list
/// of `(title, severity, description)` tuples.
fn make_risk_register_section(rows: &[(&str, &str, &str)]) -> GeneratedSection {
    GeneratedSection {
        kind: SectionKind::RiskRegister,
        source: SectionSource::AutoGenerated,
        items: rows
            .iter()
            .map(|(title, severity, desc)| SectionItem::RiskRow {
                title: Arc::from(*title),
                severity: Arc::from(*severity),
                description: Arc::from(*desc),
                owner: Arc::from("TBD"),
            })
            .collect(),
        heading: Arc::from("Risk Register"),
        target_formats: vec![OutputFormat::Docx, OutputFormat::Pdf],
        register_content: vec![],
    }
}

/// Build a manually-authored [`GeneratedSection`] with the given name and
/// report content paragraph.
fn make_manual_section(name: &str, report_text: &str) -> GeneratedSection {
    GeneratedSection {
        kind: SectionKind::ManualSection(Arc::from(name)),
        source: SectionSource::ManuallyAuthored,
        items: vec![],
        heading: Arc::from(capitalize_first(name)),
        target_formats: vec![OutputFormat::Docx, OutputFormat::Pdf],
        register_content: vec![RegisteredContent::plain(
            Register::Report,
            Arc::from(report_text),
        )],
    }
}

/// Capitalize the first character of a string (for heading generation).
fn capitalize_first(s: &str) -> String {
    let mut chars = s.chars();
    match chars.next() {
        None => String::new(),
        Some(c) => c.to_uppercase().collect::<String>() + chars.as_str(),
    }
}

/// Build a [`LaidOutDeck`] wrapping the provided slides and sections.
fn make_laid_out_deck(slides: Vec<LaidOutSlide>, sections: Vec<GeneratedSection>) -> LaidOutDeck {
    LaidOutDeck {
        page_size: PageSize::default(),
        slides,
        sections,
        warnings: vec![],
    }
}

/// Call `DocxExporter::export` and return the raw `.docx` bytes.
fn export_deck(deck: &Deck, laid_out: &LaidOutDeck) -> Vec<u8> {
    let brand = minimal_brand();
    let opts = ExportOptions::default();
    DocxExporter
        .export(deck, laid_out, &brand, &opts)
        .expect("export must succeed")
}

/// Read a named ZIP member from a `.docx` byte buffer as a UTF-8 string.
fn read_zip_member(docx_bytes: &[u8], name: &str) -> String {
    let cursor = std::io::Cursor::new(docx_bytes);
    let mut archive = zip::ZipArchive::new(cursor).expect("valid zip");
    let mut entry = archive.by_name(name).expect("member must exist");
    let mut buf = String::new();
    entry.read_to_string(&mut buf).expect("valid utf-8");
    buf
}

/// Collect the byte positions of all `Heading1` occurrences in a document XML
/// string.
///
/// Used by ordering tests to assert that narrative headings precede section
/// headings. Returns positions in document order (increasing).
#[allow(dead_code)] // used in AC-004 ordering assertion and future snapshot tests
fn find_heading1_positions(doc_xml: &str) -> Vec<usize> {
    let mut positions = Vec::new();
    let mut search = doc_xml;
    let mut base_offset = 0_usize;

    while let Some(rel_pos) = search.find("Heading1") {
        let abs_pos = base_offset + rel_pos;
        positions.push(abs_pos);
        let advance = rel_pos + "Heading1".len();
        base_offset += advance;
        search = &search[rel_pos + "Heading1".len()..];
    }
    positions
}

// ─── AC-001: executive_summary from takeaway fields ───────────────────────────

/// BC-4.02.002 postcondition 2 / AC-001:
/// A 2-slide deck where each slide has a takeaway produces a DOCX with:
/// 1. A `Heading1` paragraph "Executive Summary"
/// 2. Two bullet paragraphs: "Key finding: X" and "Key finding: Y"
///
/// RED: will panic at `todo!()` in section serialization.
#[test]
fn test_BC_4_02_002_ac001_executive_summary_from_takeaway() {
    let deck = minimal_deck();
    let slide1 = make_slide("Slide One");
    let slide2 = {
        let mut s = make_slide("Slide Two");
        s.source_index = 1;
        s
    };
    let exec_summary = make_executive_summary_section(&["Key finding: X", "Key finding: Y"]);
    let laid_out = make_laid_out_deck(vec![slide1, slide2], vec![exec_summary]);

    let docx_bytes = export_deck(&deck, &laid_out);
    let doc_xml = read_zip_member(&docx_bytes, "word/document.xml");

    assert!(
        doc_xml.contains("Executive Summary"),
        "word/document.xml must contain 'Executive Summary' heading (AC-001); \
         got:\n{doc_xml}"
    );
    assert!(
        doc_xml.contains("Key finding: X"),
        "word/document.xml must contain takeaway 'Key finding: X' (AC-001)"
    );
    assert!(
        doc_xml.contains("Key finding: Y"),
        "word/document.xml must contain takeaway 'Key finding: Y' (AC-001)"
    );
}

// ─── AC-001 canonical test vector (BC-4.02.002 canonical test vectors table) ──

/// BC-4.02.002 canonical test vector / AC-001:
/// `Deck with takeaway "Key finding: X" on 2 slides` →
/// `.docx executive_summary section with 2 takeaway paragraphs`.
///
/// RED: will panic at `todo!()` in section serialization.
#[test]
fn test_BC_4_02_002_executive_summary_two_takeaway_bullets() {
    let deck = minimal_deck();
    let slide = make_slide("Insights Slide");
    let exec_summary = make_executive_summary_section(&["Key finding: Alpha", "Key finding: Beta"]);
    let laid_out = make_laid_out_deck(vec![slide], vec![exec_summary]);

    let docx_bytes = export_deck(&deck, &laid_out);
    let doc_xml = read_zip_member(&docx_bytes, "word/document.xml");

    // Must have the heading.
    assert!(
        doc_xml.contains("Executive Summary"),
        "document.xml must contain 'Executive Summary' heading (canonical test vector)"
    );

    // Both takeaway texts must appear.
    assert!(
        doc_xml.contains("Key finding: Alpha"),
        "document.xml must contain first takeaway bullet (canonical test vector)"
    );
    assert!(
        doc_xml.contains("Key finding: Beta"),
        "document.xml must contain second takeaway bullet (canonical test vector)"
    );

    // Count occurrences of each takeaway — they must each appear exactly once.
    let count_alpha = doc_xml.matches("Key finding: Alpha").count();
    let count_beta = doc_xml.matches("Key finding: Beta").count();
    assert_eq!(
        count_alpha, 1,
        "first takeaway must appear exactly once; found {count_alpha}"
    );
    assert_eq!(
        count_beta, 1,
        "second takeaway must appear exactly once; found {count_beta}"
    );
}

// ─── AC-002: risk_register table from severity_cards slides ───────────────────

/// BC-4.02.002 postcondition 3 / AC-002:
/// A deck with 3 `severity_cards` (HIGH, MED, LOW) produces a DOCX with:
/// 1. A `Heading1` paragraph "Risk Register"
/// 2. A `<w:tbl>` with 1 header row + 3 data rows (4 total)
///
/// RED: will panic at `todo!()` in section serialization.
#[test]
fn test_BC_4_02_002_ac002_risk_register_table_row_count() {
    let deck = minimal_deck();
    let slide = make_slide("Risk Slide");
    let risk_register = make_risk_register_section(&[
        ("R001", "HIGH", "Infrastructure outage risk"),
        ("R002", "MED", "Vendor dependency risk"),
        ("R003", "LOW", "Documentation gap"),
    ]);
    let laid_out = make_laid_out_deck(vec![slide], vec![risk_register]);

    let docx_bytes = export_deck(&deck, &laid_out);
    let doc_xml = read_zip_member(&docx_bytes, "word/document.xml");

    assert!(
        doc_xml.contains("Risk Register"),
        "word/document.xml must contain 'Risk Register' heading (AC-002)"
    );
    assert!(
        doc_xml.contains("<w:tbl"),
        "word/document.xml must contain a <w:tbl> table for risk register (AC-002)"
    );

    // Count table rows: 1 header + 3 data = 4 total.
    let tr_count = doc_xml.matches("<w:tr").count();
    assert_eq!(
        tr_count, 4,
        "risk register table must have 4 rows (1 header + 3 data); found {tr_count} <w:tr> \
         elements (AC-002)"
    );
}

