// ─── AC-004: section ordering (narrative → auto → manual) ────────────────────

/// BC-4.02.002 postcondition 5 / AC-004:
/// A deck with narrative slides + risk_register (auto) + methodology (manual)
/// produces a DOCX where the order is:
/// 1. Per-slide narrative headings (Heading1 for slides)
/// 2. "Risk Register" (auto)
/// 3. "Methodology" (manual)
///
/// RED: will panic at `todo!()` in section serialization.
#[test]
fn test_BC_4_02_002_ac004_section_ordering_narrative_auto_manual() {
    let deck = minimal_deck();
    let slide = make_slide("Q1 Analysis");
    let risk_register = make_risk_register_section(&[("R001", "HIGH", "Critical risk item")]);
    let methodology = make_manual_section("methodology", "Methodology body text.");
    // sections: auto before manual in the sections vec per BC-4.02.002 ordering
    let laid_out = make_laid_out_deck(vec![slide], vec![risk_register, methodology]);

    let docx_bytes = export_deck(&deck, &laid_out);
    let doc_xml = read_zip_member(&docx_bytes, "word/document.xml");

    // All three headings must be present.
    assert!(
        doc_xml.contains("Q1 Analysis"),
        "narrative heading 'Q1 Analysis' must be present (AC-004)"
    );
    assert!(
        doc_xml.contains("Risk Register"),
        "'Risk Register' heading must be present (AC-004)"
    );
    assert!(
        doc_xml.contains("Methodology"),
        "'Methodology' heading must be present (AC-004)"
    );

    // Order assertion: narrative < risk register < methodology.
    let narrative_pos = doc_xml
        .find("Q1 Analysis")
        .expect("narrative heading must be in document.xml");
    let risk_pos = doc_xml
        .find("Risk Register")
        .expect("Risk Register heading must be in document.xml");
    let methodology_pos = doc_xml
        .find("Methodology")
        .expect("Methodology heading must be in document.xml");

    assert!(
        narrative_pos < risk_pos,
        "narrative heading must appear BEFORE risk register (AC-004 postcondition 5): \
         narrative at {narrative_pos}, risk_register at {risk_pos}"
    );
    assert!(
        risk_pos < methodology_pos,
        "risk register must appear BEFORE methodology (AC-004 postcondition 5): \
         risk_register at {risk_pos}, methodology at {methodology_pos}"
    );
}

// ─── AC-005: auto-section absent when no source slides ────────────────────────

/// BC-4.02.002 invariant 2 / AC-005:
/// A deck with no `severity_cards` slides (no risk_register section in IR)
/// produces a DOCX with NO "Risk Register" section.
///
/// RED: implicitly depends on the correct behavior — if serialize_section is
/// called on an empty-items section and panics at todo!(), this will fail there.
/// The assertion will also fail if sections are incorrectly emitted.
#[test]
fn test_BC_4_02_002_ac005_risk_register_absent_when_no_severity_cards() {
    let deck = minimal_deck();
    let slide = make_slide("Normal Slide");
    // No risk_register section in the LaidOutDeck.sections.
    let laid_out = make_laid_out_deck(vec![slide], vec![]);

    let docx_bytes = export_deck(&deck, &laid_out);
    let doc_xml = read_zip_member(&docx_bytes, "word/document.xml");

    assert!(
        !doc_xml.contains("Risk Register"),
        "word/document.xml must NOT contain 'Risk Register' when no risk sections \
         are present (AC-005 / BC-4.02.002 invariant 2); got:\n{doc_xml}"
    );
    assert!(
        !doc_xml.contains("<w:tbl"),
        "word/document.xml must NOT contain any table when no risk register section \
         is present (AC-005)"
    );

    // BleedChecker: "Risk Register" must not appear anywhere in the DOCX body.
    BleedChecker::assert_absent_from_docx_body(&docx_bytes, "Risk Register");
}

