// ─── AC-007: manual section NOT merged with auto-generated section ─────────────

/// BC-4.02.002 invariant 3 / AC-007:
/// A deck with only a manual `section methodology:` produces exactly ONE
/// "Methodology" heading. There must not be a duplicate auto-generated section
/// of the same name (since no auto-methodology rule exists by default).
///
/// RED: will panic at `todo!()` in section serialization.
#[test]
fn test_BC_4_02_002_ac007_manual_section_not_merged_with_auto() {
    let deck = minimal_deck();
    let slide = make_slide("Analysis Slide");
    let methodology = make_manual_section("methodology", "Manual methodology text.");
    // Only one manual section — no auto-generated section of the same name.
    let laid_out = make_laid_out_deck(vec![slide], vec![methodology]);

    let docx_bytes = export_deck(&deck, &laid_out);
    let doc_xml = read_zip_member(&docx_bytes, "word/document.xml");

    // "Methodology" heading must appear exactly once (the manual section).
    let count = doc_xml.matches("Methodology").count();
    assert!(
        count >= 1,
        "word/document.xml must contain at least one 'Methodology' occurrence \
         for the manual section (AC-007)"
    );

    // The manual section body must be present.
    assert!(
        doc_xml.contains("Manual methodology text."),
        "word/document.xml must contain the manual section body text (AC-007)"
    );
}

// ─── AC-008: 20 severity_cards → 20-row table ────────────────────────────────

/// BC-4.02.002 EC-005 / AC-008:
/// A deck with 20 severity_cards slides produces a risk_register table with
/// exactly 20 data rows (21 total rows including the header).
///
/// RED: will panic at `todo!()` in section serialization.
#[test]
fn test_BC_4_02_002_ac008_twenty_severity_cards_twenty_rows() {
    let deck = minimal_deck();
    let slide = make_slide("Risk Overview");

    // Build 20 RiskRow items.
    let rows: Vec<(&str, &str, &str)> = (0..20)
        .map(|i| {
            // Use static strings — Rust requires string literals for this pattern.
            // We build the strings inline via leak (test-only allocation).
            let title: &'static str = Box::leak(format!("R{i:03}").into_boxed_str());
            let severity: &'static str = if i % 3 == 0 {
                "HIGH"
            } else if i % 3 == 1 {
                "MED"
            } else {
                "LOW"
            };
            let desc: &'static str =
                Box::leak(format!("Risk description for item {i}").into_boxed_str());
            (title, severity, desc)
        })
        .collect();

    // Convert to &str tuples and build section.
    let row_refs: Vec<(&str, &str, &str)> = rows
        .iter()
        .map(|&(t, s, d)| (t, s, d))
        .collect();

    let risk_register = make_risk_register_section(&row_refs);
    let laid_out = make_laid_out_deck(vec![slide], vec![risk_register]);

    let docx_bytes = export_deck(&deck, &laid_out);
    let doc_xml = read_zip_member(&docx_bytes, "word/document.xml");

    // Count <w:tr elements: 1 header + 20 data = 21.
    let tr_count = doc_xml.matches("<w:tr").count();
    assert_eq!(
        tr_count, 21,
        "risk register table must have 21 rows (1 header + 20 data) for 20 risk items; \
         found {tr_count} <w:tr> elements (AC-008 / BC-4.02.002 EC-005)"
    );
}

