// ─── SectionOrderer unit tests ────────────────────────────────────────────────

/// BC-4.02.002 postcondition 5 (ordering) — `SectionOrderer`:
/// Auto-generated sections are returned before manually-authored sections.
///
/// RED: will panic at `todo!()` in `SectionOrderer::ordered_sections`.
#[test]
fn test_BC_4_02_002_section_orderer_auto_before_manual() {
    use crate::section_order::SectionOrderer;

    let slide = make_slide("Test");
    let risk_register = make_risk_register_section(&[("R001", "HIGH", "Risk")]);
    let methodology = make_manual_section("methodology", "Methodology body.");
    // sections vec: [risk_register (auto), methodology (manual)]
    let laid_out = make_laid_out_deck(vec![slide], vec![risk_register, methodology]);

    let orderer = SectionOrderer::new(&laid_out);
    let ordered = orderer.ordered_sections();

    assert_eq!(
        ordered.len(),
        2,
        "ordered_sections must return both sections; got {}",
        ordered.len()
    );

    // First section must be auto-generated (risk_register).
    assert_eq!(
        ordered[0].source,
        SectionSource::AutoGenerated,
        "first section in ordered output must be AutoGenerated (postcondition 5)"
    );

    // Second section must be manually-authored (methodology).
    assert_eq!(
        ordered[1].source,
        SectionSource::ManuallyAuthored,
        "second section in ordered output must be ManuallyAuthored (postcondition 5)"
    );
}

/// BC-4.02.002 invariant 2 (empty-section guard) — `SectionOrderer::auto_sections`:
/// An auto-generated section with zero items must NOT be returned.
///
/// RED: will panic at `todo!()` in `SectionOrderer::auto_sections`.
#[test]
fn test_BC_4_02_002_section_orderer_empty_auto_not_returned() {
    use crate::section_order::SectionOrderer;

    let slide = make_slide("Test");
    // Build an empty auto-generated section (0 items).
    let empty_exec_summary = GeneratedSection {
        kind: SectionKind::ExecutiveSummary,
        source: SectionSource::AutoGenerated,
        items: vec![], // empty — must not be returned by auto_sections()
        heading: Arc::from("Executive Summary"),
        target_formats: vec![OutputFormat::Docx, OutputFormat::Pdf],
        register_content: vec![],
    };
    let laid_out = make_laid_out_deck(vec![slide], vec![empty_exec_summary]);

    let orderer = SectionOrderer::new(&laid_out);
    let auto = orderer.auto_sections();

    assert!(
        auto.is_empty(),
        "auto_sections() must return empty vec for a section with zero items \
         (BC-4.02.002 invariant 2 empty-section guard); got {} sections",
        auto.len()
    );
}

// ─── Structural OOXML parse-back with sections present ────────────────────────

/// BC-4.02.002 postcondition 6 / structural validity:
/// `word/document.xml` must parse back through ooxmlsdk after a deck with
/// both auto and manual sections is exported.
///
/// RED: will panic at `todo!()` in section serialization.
#[test]
fn test_BC_4_02_002_ooxml_parse_back_document_with_sections() {
    use ooxmlsdk::schemas::schemas_openxmlformats_org_wordprocessingml_2006_main::Document;
    #[allow(unused_imports)]
    use ooxmlsdk::sdk::SdkType;

    let deck = minimal_deck();
    let slide = make_slide("Overview Slide");
    let exec_summary = make_executive_summary_section(&["Key finding: Production is stable."]);
    let risk_register = make_risk_register_section(&[("R001", "HIGH", "Critical infrastructure")]);
    let methodology = make_manual_section("methodology", "Standard methodology applied.");
    let laid_out = make_laid_out_deck(
        vec![slide],
        vec![exec_summary, risk_register, methodology],
    );

    let docx_bytes = export_deck(&deck, &laid_out);
    let doc_xml = read_zip_member(&docx_bytes, "word/document.xml");

    let document = Document::from_bytes(doc_xml.as_bytes()).unwrap_or_else(|e| {
        panic!(
            "word/document.xml must deserialize through ooxmlsdk::Document without error \
             after section serialization (BC-4.02.002 postcondition 6); \
             error: {e}\nGot:\n{doc_xml}"
        )
    });

    assert!(
        document.body.is_some(),
        "word/document.xml must have a <w:body> element after ooxmlsdk parse-back \
         with sections present (BC-4.02.002 postcondition 6)"
    );
}

// ─── BC-4.02.002 canonical test vector: no auto-generatable slides ────────────

/// BC-4.02.002 canonical test vector:
/// `Deck with no auto-generatable slides` →
/// `.docx has only per-slide narrative body; no auto sections`.
///
/// WIRING-EXEMPT: This test verifies an already-working path (empty sections
/// vec → no section XML emitted). It passes today because `DocumentBodySerializer`
/// already handles the empty `sections` case correctly — it does not call any
/// section serializer. The test is included for BC completeness and regression
/// coverage. Rationale: if Step 4 introduces a regression where section
/// serializers are called on an empty list and panic, this test catches it.
#[test]
fn test_BC_4_02_002_canonical_no_auto_sections_in_deck() {
    let deck = minimal_deck();
    let slide = make_slide("Solo Slide");
    // No sections at all in LaidOutDeck.sections.
    let laid_out = make_laid_out_deck(vec![slide], vec![]);

    let docx_bytes = export_deck(&deck, &laid_out);
    let doc_xml = read_zip_member(&docx_bytes, "word/document.xml");

    // The per-slide narrative heading must be present.
    assert!(
        doc_xml.contains("Solo Slide"),
        "per-slide heading 'Solo Slide' must be present in document.xml (canonical vector)"
    );

    // No auto-section headings.
    assert!(
        !doc_xml.contains("Executive Summary"),
        "document.xml must NOT contain 'Executive Summary' when no takeaways (canonical vector)"
    );
    assert!(
        !doc_xml.contains("Risk Register"),
        "document.xml must NOT contain 'Risk Register' when no risk sections (canonical vector)"
    );
    assert!(
        !doc_xml.contains("<w:tbl"),
        "document.xml must NOT contain any table when no risk sections (canonical vector)"
    );
}
